    "id": "fc-encor-d6-083",
    "category": "ENCOR-D6 : Infrastructure as Code & Drift Detection",
    "moduleCode": "ENCOR-D6",
    "moduleName": "Cisco CCNP ENCOR 350-401 - 6.0 Automation",
    "difficulty": "Intermédiaire",
