    "moduleCode": "ENCOR-D6",
    "moduleName": "Cisco CCNP ENCOR 350-401 - 6.0 Automation",
    "difficulty": "Intermédiaire",
    "frontTitle": "L'Opération NETCONF `<copy-config>` pour la Sauvegarde et Restauration",
